-- ============================================================
-- CAIRO METRO CAPSTONE PROJECT
-- Full script: create database -> create tables -> insert data
-- (real rows copied in directly from the CSV files) -> 10 SQL
-- queries answering the business questions.
-- Paste this whole file into MySQL Workbench and run top to bottom.
-- No file paths, no LOAD DATA, no local_infile setting needed --
-- all the data is embedded directly in this script as INSERT
-- statements.
-- ============================================================


-- ============================================================
-- STEP 1: CREATE THE DATABASE
-- ============================================================
DROP DATABASE IF EXISTS cairo_metro;
CREATE DATABASE cairo_metro;
USE cairo_metro;


-- ============================================================
-- STEP 2: CREATE THE TABLES
-- Only the 8 tables actually needed to answer the 10 business
-- questions are created, to keep the schema easy to explain.
-- ============================================================

-- Dimension table: one row per metro station
CREATE TABLE Dim_Station (
    station_id        INT PRIMARY KEY,
    station_name      VARCHAR(100),
    line_id           VARCHAR(30),
    line_position     INT,
    latitude          DECIMAL(9,6),
    longitude         DECIMAL(9,6),
    passenger_base    INT,
    is_business_area  TINYINT,
    popularity_level  VARCHAR(20),
    is_transfer       TINYINT,
    line_category     VARCHAR(30)
);

-- Dimension table: one row per calendar day in 2024
CREATE TABLE Dim_Date (
    Date            DATE PRIMARY KEY,
    Year            INT,
    Month           INT,
    MonthName       VARCHAR(10),
    MonthYear       VARCHAR(15),
    Quarter         VARCHAR(5),
    DayOfWeek       VARCHAR(10),
    DayOfWeekNum    INT,
    MonthStart      DATE,
    IsWeekend       TINYINT,
    MonthNameSort   INT
);

-- Fact table: total system performance per month
CREATE TABLE Monthly_KPIs (
    year                    INT,
    month                   INT,
    total_trips             INT,
    total_passengers        INT,
    total_revenue_egp       INT,
    avg_ticket_price        DECIMAL(6,2),
    avg_passengers_per_trip DECIMAL(6,2),
    total_service_events    INT,
    total_delay_minutes     INT,
    MonthStart              DATE,
    PRIMARY KEY (year, month)
);

-- Fact table: revenue per metro line per day
CREATE TABLE Daily_Revenue_by_Line (
    line_id           VARCHAR(30),
    date              DATE,
    total_revenue_egp INT,
    total_trips       INT,
    total_passengers  INT,
    PRIMARY KEY (line_id, date)
);

-- Fact table: passenger throughput (boardings + arrivals) per station per month
CREATE TABLE Station_Throughput_Monthly (
    station_id                  INT,
    station_name                VARCHAR(100),
    line_id                     VARCHAR(30),
    month                        INT,
    MonthStart                  DATE,
    dep_passengers               INT,
    arr_passengers               INT,
    total_throughput_passengers  INT,
    dep_trips                   INT,
    arr_trips                   INT,
    total_throughput_trips       INT,
    PRIMARY KEY (station_id, month),
    FOREIGN KEY (station_id) REFERENCES Dim_Station(station_id)
);

-- Fact table: top 200 origin -> destination station pairs
CREATE TABLE OD_Top_Pairs (
    origin_station_id      INT,
    destination_station_id INT,
    total_trips             INT,
    total_passengers        INT,
    total_revenue_egp       INT,
    origin_station_name     VARCHAR(100),
    origin_line_id          VARCHAR(30),
    destination_station_name VARCHAR(100),
    destination_line_id     VARCHAR(30),
    route                    VARCHAR(150),
    PRIMARY KEY (origin_station_id, destination_station_id)
);

-- Fact table: delay summary per station (already aggregated by the pipeline)
CREATE TABLE Station_Delays (
    station_id             INT PRIMARY KEY,
    station_name            VARCHAR(100),
    line_id                 VARCHAR(30),
    number_of_delays         INT,
    avg_delay_duration_min   DECIMAL(6,2),
    total_delay_duration_min INT,
    most_common_event_type   VARCHAR(50),
    most_common_reason       VARCHAR(50)
);

-- Fact table: average ridership per hour of the day
CREATE TABLE Time_of_Day (
    period_of_day       VARCHAR(20),
    hour                 INT PRIMARY KEY,
    avg_passenger_count  DECIMAL(6,2),
    total_trips          INT,
    period_sort          INT
);


-- ============================================================
-- STEP 3: INSERT THE DATA
-- Every row below was copied directly from the CSV files inside
-- metro_powerbi_ready_package_1.zip. Values are grouped into
-- batches of 200 rows per INSERT statement to keep each statement
-- a manageable size.
-- ============================================================

