-- Quick sanity check: row counts should match the CSV files
SELECT 'Dim_Station' AS table_name, COUNT(*) AS row_count FROM Dim_Station
UNION ALL SELECT 'Dim_Date', COUNT(*) FROM Dim_Date
UNION ALL SELECT 'Monthly_KPIs', COUNT(*) FROM Monthly_KPIs
UNION ALL SELECT 'Daily_Revenue_by_Line', COUNT(*) FROM Daily_Revenue_by_Line
UNION ALL SELECT 'Station_Throughput_Monthly', COUNT(*) FROM Station_Throughput_Monthly
UNION ALL SELECT 'OD_Top_Pairs', COUNT(*) FROM OD_Top_Pairs
UNION ALL SELECT 'Station_Delays', COUNT(*) FROM Station_Delays
UNION ALL SELECT 'Time_of_Day', COUNT(*) FROM Time_of_Day;


-- ============================================================
-- STEP 4: THE 10 BUSINESS QUESTIONS
-- ============================================================

-- ----------------------------------------------------------------
-- Q1. Which stations have the highest passenger throughput
--     (boardings + arrivals), and how does the ranking shift
--     month to month across 2024?
-- ----------------------------------------------------------------
SELECT
    stm.month,
    ds.station_name,
    ds.line_id,
    stm.total_throughput_passengers
FROM Station_Throughput_Monthly stm
JOIN Dim_Station ds
    ON stm.station_id = ds.station_id
ORDER BY stm.month ASC, stm.total_throughput_passengers DESC;


-- ----------------------------------------------------------------
-- Q2. How does total ridership vary across the four seasons
--     (Winter, Spring, Summer, Autumn)?
-- ----------------------------------------------------------------
SELECT
    CASE
        WHEN month IN (12, 1, 2) THEN 'Winter'
        WHEN month IN (3, 4, 5)  THEN 'Spring'
        WHEN month IN (6, 7, 8)  THEN 'Summer'
        ELSE 'Autumn'
    END AS season,
    SUM(total_passengers) AS total_ridership
FROM Monthly_KPIs
GROUP BY season
ORDER BY total_ridership DESC;


-- ----------------------------------------------------------------
-- Q3. What are the most heavily traveled origin-destination
--     routes, and how much trip volume and revenue do they
--     generate?
-- ----------------------------------------------------------------
SELECT
    route,
    origin_line_id,
    destination_line_id,
    total_trips,
    total_passengers,
    total_revenue_egp
FROM OD_Top_Pairs
ORDER BY total_trips DESC
LIMIT 10;


-- ----------------------------------------------------------------
-- Q4. Which stations experience the highest number of service
--     delays, and what is the most common cause at each one?
-- ----------------------------------------------------------------
SELECT
    station_name,
    line_id,
    number_of_delays,
    most_common_event_type,
    most_common_reason
FROM Station_Delays
ORDER BY number_of_delays DESC
LIMIT 10;


-- ----------------------------------------------------------------
-- Q5. Do transfer stations (two lines meet) have higher
--     throughput and more delays than single-line stations?
-- ----------------------------------------------------------------
SELECT
    CASE WHEN ds.is_transfer = 1 THEN 'Transfer Station' ELSE 'Single-Line Station' END AS station_type,
    ROUND(AVG(annual.total_annual_throughput), 0) AS avg_annual_throughput,
    ROUND(AVG(COALESCE(sd.number_of_delays, 0)), 1) AS avg_number_of_delays
FROM Dim_Station ds
JOIN (
    SELECT station_id, SUM(total_throughput_passengers) AS total_annual_throughput
    FROM Station_Throughput_Monthly
    GROUP BY station_id
) AS annual
    ON ds.station_id = annual.station_id
LEFT JOIN Station_Delays sd
    ON ds.station_id = sd.station_id
GROUP BY station_type;


-- ----------------------------------------------------------------
-- Q6. Which metro line generates the highest daily revenue,
--     and how does that revenue trend across the year?
-- ----------------------------------------------------------------
SELECT
    line_id,
    MONTH(date) AS month_num,
    SUM(total_revenue_egp) AS monthly_revenue,
    SUM(total_trips) AS monthly_trips
FROM Daily_Revenue_by_Line
GROUP BY line_id, MONTH(date)
ORDER BY monthly_revenue DESC;


-- ----------------------------------------------------------------
-- Q7. How does ticket revenue on weekends compare to revenue
--     on?
-- -------- regular weekdays--------------------------------------------------------
SELECT
    CASE WHEN dd.IsWeekend = 1 THEN 'Weekend' ELSE 'Weekday' END AS day_type,
    SUM(dr.total_revenue_egp) AS total_revenue,
    ROUND(AVG(dr.total_revenue_egp), 0) AS avg_daily_revenue_per_line
FROM Daily_Revenue_by_Line dr
JOIN Dim_Date dd
    ON dr.date = dd.Date
GROUP BY day_type;


-- ----------------------------------------------------------------
-- Q8. Geographically, where are the busiest stations
--     concentrated, and which line do they belong to?
-- ----------------------------------------------------------------
SELECT
    ds.station_name,
    ds.line_id,
    ds.latitude,
    ds.longitude,
    SUM(stm.total_throughput_passengers) AS annual_throughput
FROM Dim_Station ds
JOIN Station_Throughput_Monthly stm
    ON ds.station_id = stm.station_id
GROUP BY ds.station_id, ds.station_name, ds.line_id, ds.latitude, ds.longitude
ORDER BY annual_throughput DESC
LIMIT 15;


-- ----------------------------------------------------------------
-- Q9. What are the exact peak ridership hours during the day,
--     and how does the morning peak compare to the evening peak
-- ----------------------------------------------------------------
SELECT
    period_of_day,
    hour,
    avg_passenger_count
FROM Time_of_Day
WHERE period_of_day IN ('Morning Peak', 'Evening Peak')
ORDER BY period_of_day, avg_passenger_count DESC;


-- ----------------------------------------------------------------
-- Q10. What is the average passenger count per trip during peak
--      hours compared to off-peak hours, system-wide?
-- ----------------------------------------------------------------
SELECT
    period_of_day,
    ROUND(AVG(avg_passenger_count), 2) AS avg_passengers_per_trip,
    SUM(total_trips) AS total_trips
FROM Time_of_Day
GROUP BY period_of_day
HAVING AVG(avg_passenger_count) > 25
ORDER BY avg_passengers_per_trip DESC;
